package net.emeraldsmp.anticheat;
import net.emeraldsmp.EmeraldSMP;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.util.Vector;import java.util.*;
public final class FlightAntiCheat implements Listener{private final EmeraldSMP plugin;private final SusListManager sus;private final Map<UUID,State> states=new HashMap<>();private final Map<UUID,Long> grace=new HashMap<>();public FlightAntiCheat(EmeraldSMP p,SusListManager s){plugin=p;sus=s;}
@EventHandler public void teleport(PlayerTeleportEvent e){UUID u=e.getPlayer().getUniqueId();grace.put(u,System.currentTimeMillis()+1500);states.remove(u);}
@EventHandler public void move(PlayerMoveEvent e){Player p=e.getPlayer();UUID u=p.getUniqueId();if(exempt(p)||grace.getOrDefault(u,0L)>System.currentTimeMillis()){states.remove(u);return;}Location a=e.getFrom(),b=e.getTo();if(b==null||a.getWorld()!=b.getWorld()){states.remove(u);return;}double dy=b.getY()-a.getY(),h=Math.hypot(b.getX()-a.getX(),b.getZ()-a.getZ());Vector v=p.getVelocity();boolean ctx=p.isOnGround()||p.isInWater()||p.isSwimming()||p.isClimbing()||p.isInsideVehicle()||p.isGliding()||p.getFallDistance()>0;boolean hover=!ctx&&Math.abs(dy)<.06&&h>.10;boolean up=!ctx&&dy>.15&&v.getY()>.20;boolean still=!ctx&&Math.abs(dy)<.02&&h<.04&&Math.abs(v.getY())<.04;State s=states.computeIfAbsent(u,x->new State());if(hover||up||still){if(s.first==0)s.first=System.currentTimeMillis();s.flags++;if(s.flags>=6)sus.record(p,p.getLocation(),"Flight",s.flags,Math.min(100,s.flags*5));if(s.flags>=24&&System.currentTimeMillis()-s.first>=2500)punish(p,s.flags);}else{s.flags=Math.max(0,s.flags-2);if(s.flags==0)s.first=0;}}
private boolean exempt(Player p){GameMode g=p.getGameMode();return g==GameMode.CREATIVE||g==GameMode.SPECTATOR||p.getAllowFlight()||p.isFlying()||p.isGliding()||p.isInsideVehicle()||p.isSwimming()||p.isInWater()||p.isClimbing()||p.hasPermission("emerald.anticheat.bypass");}
private void punish(Player p,int f){sus.record(p,p.getLocation(),"Flight",f,Math.min(100,f*5));Bukkit.getLogger().info("[Emerald AntiCheat] "+p.getName()+" flagged for unauthorized flight ("+f+" observations).");p.setAllowFlight(false);p.setFlying(false);p.kickPlayer("§c§lEMERALD SMP\n§fUnauthorized flight detected.\n§7You have been kicked for review.\n\n§8Staff can review §f/suslist§8.");states.remove(p.getUniqueId());}
@EventHandler public void quit(PlayerQuitEvent e){UUID u=e.getPlayer().getUniqueId();states.remove(u);grace.remove(u);}private static final class State{int flags;long first;}}
